import type { Metadata } from "next";

import { siteConfig } from "@/lib/site";

/**
 * Social images generated by app/opengraph-image.tsx and app/twitter-image.tsx.
 * A page that sets `openGraph`/`twitter` replaces the inherited objects, so the
 * images must be listed again explicitly.
 */
export const SOCIAL_IMAGE_ALT = `${siteConfig.name}: Does AI recommend your business?`;
const OG_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: SOCIAL_IMAGE_ALT };
const TWITTER_IMAGE = { url: "/twitter-image", width: 1200, height: 630, alt: SOCIAL_IMAGE_ALT };

/**
 * Per-page metadata for public marketing pages: title, description,
 * canonical URL, Open Graph and Twitter card. The root layout supplies
 * `metadataBase` and the "%s · AI Visibility" title template.
 */
export function marketingMetadata({
  title,
  description,
  path,
  absoluteTitle = false,
}: {
  title: string;
  description: string;
  /** Canonical path, e.g. "/pricing". */
  path: string;
  /** Use `title` verbatim instead of applying the site title template. */
  absoluteTitle?: boolean;
}): Metadata {
  const socialTitle = absoluteTitle ? title : `${title} · ${siteConfig.shortName}`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: siteConfig.name,
      locale: "en_US",
      url: path,
      title: socialTitle,
      description,
      images: [OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description,
      images: [TWITTER_IMAGE],
    },
  };
}
